    private PLZArmClearanceMesh() {
    }

    /** Rows: side mask (1 left, 2 right), influence count, then per influence bone, weight, bone-local x, y, z. */
    static final class Body {
        final String[] bones;
        final float[] armRadius;
        final float[] reference;
        final float[] rows;

        Body(String[] bones, float[] armRadius, float[] reference, String rows) {
            this.bones = bones;
            this.armRadius = armRadius;
            this.reference = reference;
            String[] parts = rows.split(",");
            this.rows = new float[parts.length];
            for (int i = 0; i < parts.length; i++) {
                this.rows[i] = Float.parseFloat(parts[i]);
            }
        }
    }
